package com.dorm.platform.notice.service;
import com.dorm.platform.common.*;
import com.dorm.platform.security.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.time.*;
import java.util.*;
import static com.dorm.platform.common.Input.*;
@Service
public class NoticeService {
 private final SqlStore db; private final DataScope scope;
 public NoticeService(SqlStore db,DataScope scope){this.db=db;this.scope=scope;}
 public void send(Collection<Long> users,String title,String content){if(users.isEmpty())return;long id=db.insert("INSERT INTO site_message(target_role,title,content,delivered_at) VALUES('DIRECT',?,?,NOW())",title,content);for(long user:new HashSet<>(users))db.update("INSERT INTO message_receipt(message_id,user_id) VALUES(?,?)",id,user);}
 public void managers(long building,String title,String content){send(db.rows("SELECT manager_user_id FROM manager_building_scope WHERE building_id=?",building).stream().map(x->id(x.get("manager_user_id"))).toList(),title,content);}
 public List<Map<String,Object>> list(CurrentUser u,Map<String,String> filters){StringBuilder sql=new StringBuilder("SELECT m.message_id,m.title,m.content,m.created_at,r.read_at,IF(r.read_at IS NULL,'未读','已读') read_label,m.publisher_user_id,p.real_name publisher_name,p.role_code publisher_role,CASE WHEN m.publisher_user_id IS NULL THEN '系统通知' WHEN p.role_code='DORM_MANAGER' THEN '宿管通知' WHEN p.role_code='ADMIN' THEN '系统管理员通知' ELSE '其他通知' END source_label");if(u.role().equals("ADMIN"))sql.append(",GROUP_CONCAT(DISTINCT b.building_name ORDER BY b.building_name SEPARATOR '、') building_names");sql.append(" FROM site_message m ");if(u.role().equals("ADMIN"))sql.append("LEFT JOIN message_receipt r ON r.message_id=m.message_id AND r.user_id=? LEFT JOIN v_user_identity p ON p.user_id=m.publisher_user_id LEFT JOIN message_target mt ON mt.message_id=m.message_id LEFT JOIN v_accommodation_current ac ON ac.student_id=mt.user_id LEFT JOIN building b ON b.building_id=ac.building_id WHERE 1=1");else sql.append("JOIN message_receipt r ON r.message_id=m.message_id AND r.user_id=? LEFT JOIN v_user_identity p ON p.user_id=m.publisher_user_id WHERE 1=1");List<Object> args=new ArrayList<>();args.add(u.id());String read=Objects.toString(filters.get("read"),"").trim();if(read.equals("read"))sql.append(" AND r.read_at IS NOT NULL");else if(read.equals("unread"))sql.append(" AND r.read_at IS NULL");String from=Objects.toString(filters.get("from"),"").trim(),to=Objects.toString(filters.get("to"),"").trim();if(!from.isEmpty()){sql.append(" AND m.created_at>=?");args.add(from+" 00:00:00");}if(!to.isEmpty()){sql.append(" AND m.created_at<DATE_ADD(?,INTERVAL 1 DAY)");args.add(to);}if(u.role().equals("ADMIN")){String sender=Objects.toString(filters.get("sender"),"").trim();if(sender.equals("SYSTEM"))sql.append(" AND m.publisher_user_id IS NULL");else if(!sender.isEmpty()){sql.append(" AND p.role_code=?");args.add(sender);}String building=Objects.toString(filters.get("building"),"").trim();if(!building.isEmpty()){sql.append(" AND m.target_role=?");args.add("BUILDING:"+building);}}sql.append(" GROUP BY m.message_id,r.read_at,p.real_name,p.role_code ORDER BY m.message_id DESC LIMIT 500");return db.rows(sql.toString(),args.toArray());}
 public List<Map<String,Object>> list(CurrentUser u){return list(u,Map.of());}
 @Transactional public void clearRead(CurrentUser u){db.update("DELETE FROM message_receipt WHERE user_id=? AND read_at IS NOT NULL",u.id());}
 public void read(CurrentUser u,long id){if(db.update("UPDATE message_receipt SET read_at=COALESCE(read_at,NOW()) WHERE message_id=? AND user_id=?",id,u.id())==0 && db.count("SELECT COUNT(*) FROM message_receipt WHERE message_id=? AND user_id=?",id,u.id())==0)throw BizException.forbidden();}
 @Transactional public void publish(CurrentUser u,Map<String,Object>b){role(u,"ADMIN","DORM_MANAGER");List<Map<String,Object>> recipients;String target=text(b,"targetRole");Long buildingId=null;if(b.get("buildingId")!=null&&!text(b,"buildingId").isBlank()){buildingId=id(b.get("buildingId"));scope.building(u,buildingId);recipients=db.rows("SELECT student_id user_id FROM v_accommodation_current WHERE building_id=?",buildingId);}else{role(u,"ADMIN");BizException.require(Set.of("ALL","STUDENT","DORM_MANAGER","REPAIRER","ADMIN").contains(target),"消息对象无效");recipients=db.rows("SELECT user_id FROM v_user_identity WHERE enabled=1 AND (?='ALL' OR role_code=?)",target,target);}
 LocalDateTime at=text(b,"publishAt").isBlank()?LocalDateTime.now().withNano(0):time(b.get("publishAt"));long msg=db.insert("INSERT INTO site_message(target_role,title,content,publisher_user_id,publish_at) VALUES('DIRECT',?,?,?,?)",required(b,"title"),required(b,"content"),u.id(),at);for(var r:recipients)db.update("INSERT INTO message_target(message_id,user_id) VALUES(?,?)",msg,r.get("user_id"));if(buildingId!=null)db.update("UPDATE site_message SET target_role=? WHERE message_id=?","BUILDING:"+buildingId,msg);deliver();db.log(u.id(),"notice","publish",msg);}
 @Transactional public void deliver(){for(var m:db.rows("SELECT message_id FROM site_message WHERE delivered_at IS NULL AND publish_at<=NOW() FOR UPDATE")){db.update("INSERT IGNORE INTO message_receipt(message_id,user_id) SELECT message_id,user_id FROM message_target WHERE message_id=?",m.get("message_id"));db.update("UPDATE site_message SET delivered_at=NOW() WHERE message_id=?",m.get("message_id"));}}
}
